// Process KAP disclosures
const disclosures = $input.all();
const processed = [];

for (const item of disclosures) {
  const disclosure = item.json;
  processed.push({
    publishing_id: disclosure.publishingId,
    title: disclosure.title,
    summary: disclosure.summary,
    body: disclosure.content,
    category: 'OTHER',
    is_material: disclosure.disclosureType === 'MATERIAL_EVENT',
    published_at: disclosure.publishDate,
    ingested_at: new Date().toISOString(),
    source_url: `https://www.kap.org.tr/tr/Bildir/${disclosure.publishingId}`
  });
}

return processed.map(d => ({ json: d }));
